#!/usr/bin/env node
// Renders Claude Code session transcripts into Context/Claude as Markdown.
// Hook usage: receives hook JSON on stdin (session_id, transcript_path).
// Manual usage: node save-transcript.js <transcript.jsonl> [...more]

const fs = require('fs');
const path = require('path');

const projectDir = path.resolve(__dirname, '..', '..');
const outDir = path.join(projectDir, 'Context', 'Claude');

function stripNoise(text) {
  return text
    .replace(/<system-reminder>[\s\S]*?<\/system-reminder>/g, '')
    .replace(/<ide_[a-z_]+>[\s\S]*?<\/ide_[a-z_]+>/g, '')
    .replace(/<(command-message|command-name|command-args|local-command-stdout)>[\s\S]*?<\/\1>/g, '')
    .trim();
}

function textOf(content) {
  if (typeof content === 'string') return content;
  if (!Array.isArray(content)) return '';
  return content.filter((c) => c.type === 'text').map((c) => c.text).join('\n\n');
}

function summarizeTool(block) {
  const input = block.input || {};
  const hint =
    input.description || input.file_path || input.command || input.pattern ||
    input.skill || input.query || input.prompt || '';
  const oneLine = String(hint).split('\n')[0].slice(0, 160);
  return `- \`${block.name}\`${oneLine ? `: ${oneLine}` : ''}`;
}

function quote(text) {
  return text.split('\n').map((l) => (l ? `> ${l}` : '>')).join('\n');
}

function render(transcriptPath) {
  const lines = fs.readFileSync(transcriptPath, 'utf8').split('\n').filter(Boolean);
  const entries = [];
  for (const line of lines) {
    try { entries.push(JSON.parse(line)); } catch { /* skip partial line */ }
  }

  const msgs = entries.filter(
    (e) => (e.type === 'user' || e.type === 'assistant') && !e.isSidechain && e.message
  );
  if (!msgs.length) return null;

  const sessionId = msgs[0].sessionId || path.basename(transcriptPath, '.jsonl');
  const started = msgs[0].timestamp ? new Date(msgs[0].timestamp) : new Date();
  const date = started.toISOString().slice(0, 10);

  const body = [];
  let title = '';
  let pendingTools = [];
  const flushTools = () => {
    if (pendingTools.length) {
      body.push('**Actions**\n\n' + pendingTools.join('\n'));
      pendingTools = [];
    }
  };

  for (const e of msgs) {
    const content = e.message.content;
    if (e.type === 'user') {
      if (e.isMeta) continue;
      if (Array.isArray(content) && content.some((c) => c.type === 'tool_result')) continue;
      const text = stripNoise(textOf(content));
      if (!text) continue;
      flushTools();
      if (!title) title = text.split('\n')[0].slice(0, 80);
      const time = e.timestamp ? new Date(e.timestamp).toISOString().slice(11, 16) + ' UTC' : '';
      body.push(`## User${time ? ` (${time})` : ''}\n\n${quote(text)}`);
    } else {
      if (!Array.isArray(content)) continue;
      for (const block of content) {
        if (block.type === 'tool_use') pendingTools.push(summarizeTool(block));
        else if (block.type === 'text' && block.text.trim()) {
          flushTools();
          body.push(`## Claude\n\n${block.text.trim()}`);
        }
      }
    }
  }
  flushTools();
  if (!title) return null;

  const file = `${date}-${sessionId.slice(0, 8)}.md`;
  const md =
    `# ${title}\n\n` +
    `Date: ${date}  \nSession: \`${sessionId}\`  \nProject: LearnSphere\n\n` +
    `Generated automatically from the Claude Code transcript. Tool calls are summarized, not transcribed.\n\n` +
    body.join('\n\n') + '\n';

  fs.mkdirSync(outDir, { recursive: true });
  fs.writeFileSync(path.join(outDir, file), md);
  return file;
}

function writeIndex() {
  const files = fs.readdirSync(outDir).filter((f) => /^\d{4}-\d{2}-\d{2}-.*\.md$/.test(f)).sort();
  const items = files.map((f) => {
    const first = fs.readFileSync(path.join(outDir, f), 'utf8').split('\n')[0].replace(/^#\s*/, '');
    return `- [${f.slice(0, 10)} — ${first}](${f})`;
  });
  const readme =
    '# Claude conversation archive\n\n' +
    'Conversations from Claude Code sessions in this project. Each file is regenerated after every turn by the ' +
    'Stop hook in `.claude/settings.json` (`.claude/hooks/save-transcript.js`).\n\n' +
    '## Conversations\n\n' + items.join('\n') + '\n';
  fs.writeFileSync(path.join(outDir, 'README.md'), readme);
}

function main(paths) {
  for (const p of paths) if (p && fs.existsSync(p)) render(p);
  if (fs.existsSync(outDir)) writeIndex();
}

const args = process.argv.slice(2);
if (args.length) {
  main(args);
} else {
  let input = '';
  process.stdin.on('data', (d) => (input += d));
  process.stdin.on('end', () => {
    let data = {};
    try { data = JSON.parse(input || '{}'); } catch { /* ignore */ }
    main([data.transcript_path]);
  });
}

