1	#!/usr/bin/env node
2	// Archives available project conversations into Context/ as sanitized publication copies.
3	// Credentials and internal reasoning are removed; originals remain in the platform session stores.
4	//
5	//   Context/Claude/raw/*.jsonl        verbatim copies of Claude Code session transcripts (+ subagent dirs)
6	//   Context/Claude/YYYY-MM-DD-<id>.md full readable rendering: every message, tool call input and tool result
7	//   Context/Codex/raw/*.jsonl         verbatim copies of Codex sessions whose cwd is this project
8	//   Context/Codex/full/YYYY-MM-DD-<id>.md  full readable rendering of those Codex sessions
9	//   Context/README.md                 index of everything above
10	//
11	// The raw .jsonl files are the unedited source of truth; the .md files are lossless-in-content views
12	// (internal bookkeeping records such as API request metadata are only in the raw files).
13	//
14	// Hook usage: Stop/SessionEnd hook, hook JSON on stdin. Manual usage: node save-transcript.js
15	// Both modes sync every session; unchanged sessions are skipped.
16	
17	const fs = require('fs');
18	const os = require('os');
19	const path = require('path');
20	const { redact, sanitizeJsonl } = require('../../scripts/archive-safety.cjs');
21	
22	function writeArchive(file, text) {
23	  fs.writeFileSync(file, file.endsWith('.jsonl') ? sanitizeJsonl(text) : redact(text));
24	}
25	
26	const projectDir = path.resolve(__dirname, '..', '..');
27	const contextDir = path.join(projectDir, 'Context');
28	const claudeOut = path.join(contextDir, 'Claude');
29	const codexOut = path.join(contextDir, 'Codex');
30	
31	// ---------- helpers ----------
32	
33	function readJsonl(file) {
34	  const out = [];
35	  for (const line of sanitizeJsonl(fs.readFileSync(file, 'utf8')).split('\n')) {
36	    if (!line.trim()) continue;
37	    try { out.push(JSON.parse(line)); } catch { /* partial line while being written */ }
38	  }
39	  return out;
40	}
41	
42	function fence(text, lang = '') {
43	  const s = String(text ?? '');
44	  const longest = Math.max(2, ...(s.match(/`+/g) || []).map((m) => m.length));
45	  const f = '`'.repeat(longest + 1);
46	  return `${f}${lang}\n${s}\n${f}`;
47	}
48	
49	function details(summary, body) {
50	  return `<details>\n<summary>${summary}</summary>\n\n${body}\n\n</details>`;
51	}
52	
53	function utc(ts) {
54	  if (!ts) return '';
55	  const d = typeof ts === 'number' ? new Date(ts < 1e12 ? ts * 1000 : ts) : new Date(ts);
56	  return isNaN(d) ? '' : d.toISOString().replace('T', ' ').slice(0, 19) + ' UTC';
57	}
58	
59	function isUpToDate(src, dest) {
60	  // Always refresh publication copies so updated redaction rules also cover older sessions.
61	  return false;
62	}
63	
64	function copyRecursive(src, dest) {
65	  const st = fs.statSync(src);
66	  if (st.isDirectory()) {
67	    fs.mkdirSync(dest, { recursive: true });
68	    for (const name of fs.readdirSync(src)) copyRecursive(path.join(src, name), path.join(dest, name));
69	  } else if (!isUpToDate(src, dest)) {
70	    fs.mkdirSync(path.dirname(dest), { recursive: true });
71	    if (src.endsWith('.jsonl')) writeArchive(dest, fs.readFileSync(src, 'utf8'));
72	    else fs.copyFileSync(src, dest);
73	  }
74	}
75	
76	function walk(dir, pred, acc = []) {
77	  if (!fs.existsSync(dir)) return acc;
78	  for (const name of fs.readdirSync(dir)) {
79	    const p = path.join(dir, name);
80	    const st = fs.statSync(p);
81	    if (st.isDirectory()) walk(p, pred, acc);
82	    else if (pred(p)) acc.push(p);
83	  }
84	  return acc;
85	}
86	
87	const sameDir = (a, b) => path.resolve(a).toLowerCase() === path.resolve(b).toLowerCase();
88	
89	// ---------- Claude Code ----------
90	
91	function claudeProjectDirs(hintTranscript) {
92	  const dirs = new Set();
93	  if (hintTranscript && fs.existsSync(hintTranscript)) dirs.add(path.dirname(hintTranscript));
94	  const root = path.join(os.homedir(), '.claude', 'projects');
95	  const sanitized = projectDir.replace(/[^A-Za-z0-9]/g, '-').toLowerCase();
96	  if (fs.existsSync(root)) {
97	    for (const name of fs.readdirSync(root)) {
98	      if (name.toLowerCase() === sanitized) dirs.add(path.join(root, name));
99	    }
100	  }
101	  return [...dirs];
102	}
103	
104	function renderClaudeBlock(block) {
105	  switch (block.type) {
106	    case 'text':
107	      return block.text;
108	    case 'thinking':
109	      return block.thinking ? details('Thinking', block.thinking) : '';
110	    case 'redacted_thinking':
111	      return '_(redacted thinking block — present in raw transcript)_';
112	    case 'tool_use':
113	      return details(`Tool call: <code>${block.name}</code>`, fence(JSON.stringify(block.input, null, 2), 'json'));
114	    case 'tool_result': {
115	      const c = block.content;
116	      const text = typeof c === 'string' ? c
117	        : Array.isArray(c) ? c.map((x) => (x.type === 'text' ? x.text : `[${x.type}]`)).join('\n') : JSON.stringify(c);
118	      return details(`Tool result${block.is_error ? ' (error)' : ''}`, fence(text));
119	    }
120	    case 'image':
121	      return '_[image]_';
122	    default:
123	      return details(`Block: ${block.type}`, fence(JSON.stringify(block, null, 2), 'json'));
124	  }
125	}
126	
127	function renderClaude(file) {
128	  const entries = readJsonl(file);
129	  const msgs = entries.filter((e) => e.type === 'user' || e.type === 'assistant' || e.type === 'system' || e.type === 'attachment');
130	  const first = msgs.find((e) => e.type === 'user' && e.message);
131	  if (!first) return null;
132	
133	  const sessionId = first.sessionId || path.basename(file, '.jsonl');
134	  const date = (first.timestamp || new Date().toISOString()).slice(0, 10);
135	  const aiTitle = [...entries].reverse().find((e) => e.type === 'ai-title');
136	  let title = '';
137	
138	  const body = [];
139	  for (const e of msgs) {
140	    const when = utc(e.timestamp);
141	    const side = e.isSidechain ? ' · subagent' : '';
142	    if (e.type === 'attachment') {
143	      body.push(details(`Attachment${when ? ` · ${when}` : ''}`, fence(JSON.stringify(e.attachment, null, 2), 'json')));
144	      continue;
145	    }
146	    if (e.type === 'system') {
147	      body.push(`### System${side}${when ? ` · ${when}` : ''}\n\n${fence(e.content ?? JSON.stringify(e, null, 2))}`);
148	      continue;
149	    }
150	    const content = e.message && e.message.content;
151	    const blocks = typeof content === 'string' ? [{ type: 'text', text: content }] : Array.isArray(content) ? content : [];
152	    const onlyResults = blocks.length && blocks.every((b) => b.type === 'tool_result');
153	    let heading;
154	    if (e.type === 'assistant') heading = `### Claude${side}`;
155	    else if (onlyResults) heading = `### Tool output${side}`;
156	    else if (e.isMeta) heading = `### Injected context${side}`;
157	    else {
158	      heading = `## User${side}`;
159	      if (!title && !e.isSidechain) {
160	        const t = blocks.filter((b) => b.type === 'text').map((b) => b.text).join(' ')
161	          .replace(/<[^>]+>[\s\S]*?<\/[^>]+>/g, '').trim();
162	        title = t.split('\n')[0].slice(0, 80);
163	      }
164	    }
165	    const rendered = blocks.map(renderClaudeBlock).filter(Boolean).join('\n\n');
166	    if (rendered) body.push(`${heading}${when ? ` · ${when}` : ''}\n\n${rendered}`);
167	  }
168	
169	  title = (aiTitle && (aiTitle.title || aiTitle.aiTitle)) || title || sessionId;
170	  const out = `${date}-${sessionId.slice(0, 8)}.md`;
171	  const md =
172	    `# ${title}\n\n` +
173	    `- Tool: Claude Code\n- Date: ${date}\n- Session: \`${sessionId}\`\n` +
174	    `- Sanitized transcript: [raw/${path.basename(file)}](raw/${path.basename(file)})\n\n` +
175	    `Rendering of available conversation records. Credentials and internal reasoning are omitted; see AI-LOGS.md. ` +
176	    `Collapsed sections hold tool inputs/outputs.\n\n---\n\n` +
177	    body.join('\n\n') + '\n';
178	  fs.mkdirSync(claudeOut, { recursive: true });
179	  writeArchive(path.join(claudeOut, out), md);
180	  return { file: out, title, date, tool: 'Claude Code', dir: 'Claude' };
181	}
182	
183	function syncClaude(hintTranscript) {
184	  const rawDir = path.join(claudeOut, 'raw');
185	  for (const dir of claudeProjectDirs(hintTranscript)) {
186	    for (const name of fs.readdirSync(dir)) {
187	      if (!name.endsWith('.jsonl')) continue;
188	      const src = path.join(dir, name);
189	      const dest = path.join(rawDir, name);
190	      const rendered = fs.existsSync(claudeOut) &&
191	        fs.readdirSync(claudeOut).some((f) => f.endsWith(`-${name.slice(0, 8)}.md`));
192	      const subDir = path.join(dir, name.replace(/\.jsonl$/, ''));
193	      if (fs.existsSync(subDir)) copyRecursive(subDir, path.join(rawDir, path.basename(subDir)));
194	      if (isUpToDate(src, dest) && rendered) continue;
195	      copyRecursive(src, dest);
196	      renderClaude(src);
197	    }
198	  }
199	}
200	
201	// ---------- Codex ----------
202	
203	function codexSessionFiles() {
204	  const roots = [path.join(os.homedir(), '.codex', 'sessions'), path.join(os.homedir(), '.codex', 'archived_sessions')];
205	  const files = [];
206	  for (const r of roots) {
207	    for (const f of walk(r, (p) => p.endsWith('.jsonl'))) {
208	      const fd = fs.openSync(f, 'r');
209	      const buf = Buffer.alloc(16384);
210	      const n = fs.readSync(fd, buf, 0, buf.length, 0);
211	      fs.closeSync(fd);
212	      const m = buf.toString('utf8', 0, n).match(/"cwd":"((?:[^"\\]|\\.)*)"/);
213	      if (m && sameDir(JSON.parse(`"${m[1]}"`), projectDir)) files.push(f);
214	    }
215	  }
216	  return files;
217	}
218	
219	function codexText(content) {
220	  if (typeof content === 'string') return content;
221	  if (!Array.isArray(content)) return JSON.stringify(content, null, 2);
222	  return content.map((c) => c.text ?? (c.type ? `[${c.type}]` : JSON.stringify(c))).join('\n');
223	}
224	
225	function renderCodex(file) {
226	  const entries = readJsonl(file);
227	  const meta = entries.find((e) => e.type === 'session_meta');
228	  const id = (meta && (meta.payload.id || meta.payload.session_id)) || path.basename(file, '.jsonl');
229	  const date = ((meta && meta.timestamp) || new Date().toISOString()).slice(0, 10);
230	  let title = '';
231	  const body = [];
232	
233	  if (meta) {
234	    const { base_instructions, ...rest } = meta.payload;
235	    body.push(details('Session metadata', fence(JSON.stringify(rest, null, 2), 'json')));
236	    if (base_instructions) {
237	      const bi = typeof base_instructions === 'string' ? base_instructions : base_instructions.text ?? JSON.stringify(base_instructions, null, 2);
238	      body.push(details('Base instructions', fence(bi)));
239	    }
240	  }
241	
242	  for (const e of entries) {
243	    if (e.type === 'event_msg' && e.payload.type === 'user_message' && !title) {
244	      const m = String(e.payload.message || '');
245	      const req = m.split('## My request:')[1] || m;
246	      title = req.trim().split('\n')[0].slice(0, 80);
247	    }
248	    if (e.type !== 'response_item') continue;
249	    const p = e.payload;
250	    const when = utc(e.timestamp);
251	    const ts = when ? ` · ${when}` : '';
252	    switch (p.type) {
253	      case 'message': {
254	        const text = codexText(p.content);
255	        if (p.role === 'user') body.push(`## User${ts}\n\n${text}`);
256	        else if (p.role === 'assistant') body.push(`### Codex${p.phase ? ` (${p.phase})` : ''}${ts}\n\n${text}`);
257	        else body.push(details(`${p.role} message${ts}`, fence(text)));
258	        break;
259	      }
260	      case 'reasoning': {
261	        const summary = (p.summary || []).map((s) => s.text).filter(Boolean).join('\n\n');
262	        body.push(summary ? details(`Reasoning summary${ts}`, summary)
263	          : '_(reasoning — encrypted by the provider; stored verbatim in the raw transcript)_');
264	        break;
265	      }
266	      case 'custom_tool_call':
267	      case 'function_call':
268	        body.push(details(`Tool call: <code>${p.name}</code>${ts}`, fence(p.input ?? p.arguments ?? '')));
269	        break;
270	      case 'custom_tool_call_output':
271	      case 'function_call_output': {
272	        const o = p.output;
273	        const text = typeof o === 'string' ? o : Array.isArray(o) ? codexText(o) : JSON.stringify(o, null, 2);
274	        body.push(details(`Tool result${ts}`, fence(text)));
275	        break;
276	      }
277	      default:
278	        body.push(details(`${p.type}${ts}`, fence(JSON.stringify(p, null, 2), 'json')));
279	    }
280	  }
281	
282	  title = title || id;
283	  const out = `${date}-${String(id).slice(0, 8)}.md`;
284	  const rawName = path.basename(file);
285	  const md =
286	    `# ${title}\n\n` +
287	    `- Tool: OpenAI Codex\n- Date: ${date}\n- Session: \`${id}\`\n` +
288	    `- Sanitized transcript: [../raw/${rawName}](../raw/${rawName})\n\n` +
289	    `Rendering of available conversation records. Credentials and internal reasoning are omitted; see AI-LOGS.md.\n\n---\n\n` +
290	    body.join('\n\n') + '\n';
291	  const fullDir = path.join(codexOut, 'full');
292	  fs.mkdirSync(fullDir, { recursive: true });
293	  writeArchive(path.join(fullDir, out), md);
294	}
295	
296	function syncCodex() {
297	  const rawDir = path.join(codexOut, 'raw');
298	  for (const src of codexSessionFiles()) {
299	    const dest = path.join(rawDir, path.basename(src));
300	    if (isUpToDate(src, dest)) continue;
301	    copyRecursive(src, dest);
302	    renderCodex(src);
303	  }
304	}
305	
306	// ---------- index ----------
307	
308	function firstHeading(file) {
309	  return fs.readFileSync(file, 'utf8').split('\n')[0].replace(/^#\s*/, '');
310	}
311	
312	function writeIndexes() {
313	  const list = (dir, rel) => (fs.existsSync(dir) ? fs.readdirSync(dir) : [])
314	    .filter((f) => /^\d{4}-\d{2}-\d{2}-.*\.md$/.test(f)).sort()
315	    .map((f) => `- [${f.slice(0, 10)} — ${firstHeading(path.join(dir, f))}](${rel}${f})`);
316	
317	  const claude = list(claudeOut, '');
318	  if (fs.existsSync(claudeOut)) {
319	    fs.writeFileSync(path.join(claudeOut, 'README.md'),
320	      '# Claude Code conversation archive\n\n' +
321	      'Available Claude Code sessions for this project, sanitized for credentials and internal reasoning (see AI-LOGS.md), saved by the ' +
322	      'Stop/SessionEnd hooks in `.claude/settings.json` (`.claude/hooks/save-transcript.js`).\n\n' +
323	      '- `raw/*.jsonl` — sanitized transcript copies\n' +
324	      '- `*.md` — full readable rendering of each session\n\n## Sessions\n\n' + claude.join('\n') + '\n');
325	  }
326	
327	  const codex = list(path.join(codexOut, 'full'), 'Codex/full/');
328	  const index =
329	    '# AI-assistant conversation logs\n\n' +
330	    'Every AI-assistant session used on this project, archived automatically by `.claude/hooks/save-transcript.js` ' +
331	    '(runs after every Claude Code turn; run `node .claude/hooks/save-transcript.js` manually to sync at any time).\n\n' +
332	    'The `raw/` folders contain publication copies with credentials redacted and internal reasoning omitted. ' +
333	    'The Markdown files render those available records. These are not unedited exports; see AI-LOGS.md for exceptions and coverage.\n\n' +
334	    '## Claude Code\n\n' + (list(claudeOut, 'Claude/').join('\n') || '_none_') + '\n\n' +
335	    '## OpenAI Codex\n\n' + (codex.join('\n') || '_none_') + '\n\n' +
336	    'Codex also keeps hand-written session notes in `Codex/` per `AGENTS.md`.\n';
337	  fs.mkdirSync(contextDir, { recursive: true });
338	  fs.writeFileSync(path.join(contextDir, 'README.md'), index);
339	}
340	
341	// ---------- main ----------
342	
343	function main(hintTranscript) {
344	  try { syncClaude(hintTranscript); } catch (err) { console.error('claude sync failed:', err.message); }
345	  try { syncCodex(); } catch (err) { console.error('codex sync failed:', err.message); }
346	  writeIndexes();
347	}
348	
349	if (process.stdin.isTTY) {
350	  main(process.argv[2]);
351	} else {
352	  let input = '';
353	  process.stdin.on('data', (d) => (input += d));
354	  process.stdin.on('end', () => {
355	    let data = {};
356	    try { data = JSON.parse(input || '{}'); } catch { /* manual run with piped junk */ }
357	    main(data.transcript_path || process.argv[2]);
358	  });
359	}
