    11	public sealed class GeminiLlmClient(HttpClient http, IOptions<LlmOptions> options) : ILlmClient
    12	{
    13	    private readonly LlmOptions config = options.Value;
    14	    private JsonObject Body(LlmRequest request)
    15	    {
    16	        var messages = new JsonArray();
